//! What the Blender add-on (`scripts/blender/oag_track`) writes, read by the real
//! reader. The files under `tests/fixtures/` are the add-on's own output, committed
//! and regenerated by `just blender-fixtures` (needs Blender 4.2 or later; the gate
//! does not, it only reads them). A stale fixture shows up as a diff after that
//! recipe, and a dropped add-on feature as one of these tests failing.

use oag_trackfile::{Loaded, Track, read};

fn load(name: &str) -> Loaded {
    let dir = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures");
    read(&dir.join(name)).unwrap_or_else(|e| panic!("{name}: {e}"))
}

/// The committed oval, imported with the add-on's importer and exported again, is
/// the same track under the crate's own equality - and bit for bit on every
/// simulation float, which `PartialEq` cannot tell for 0.0 and -0.0.
#[test]
fn the_oval_imported_into_blender_and_exported_again_is_the_same_track() {
    let (a, b) = (load("oval.track.toml"), load("oval.reexport.track.toml"));
    assert!(b.unread.is_empty(), "{:?}", b.unread);
    assert_eq!(a.track, b.track);
    let bits = |t: &Track| -> Vec<u32> {
        let mut out = Vec::new();
        for p in &t.ai.paths[0].points {
            for v in [p.pos, p.tangent, p.down, p.lateral] {
                out.extend(v.map(f32::to_bits));
            }
            out.extend([p.progress, p.half_width_left, p.ai_bound_right].map(f32::to_bits));
        }
        for n in &t.nodes {
            for m in &n.geometry.meshes {
                out.extend(m.vertices.iter().flatten().map(|v| v.to_bits()));
            }
        }
        for pad in t.speedup_pads.iter().chain(&t.weapon_pads) {
            out.extend(pad.to_world.map(f32::to_bits));
        }
        out.extend(
            t.ai.paths[0]
                .max_spacing
                .to_bits()
                .to_le_bytes()
                .map(u32::from),
        );
        out.extend(
            [t.start.position, t.start.left, t.start.up, t.start.forward]
                .iter()
                .flatten()
                .map(|v| v.to_bits()),
        );
        out
    };
    assert_eq!(bits(&a.track), bits(&b.track));
}

/// A loop built from scratch in Blender (8 control points, floor and walls built
/// by the add-on, a start, one pad of each kind) reads with nothing unread and
/// carries every record the race needs.
#[test]
fn a_loop_built_in_blender_reads_with_every_record_the_race_needs() {
    let l = load("blender_loop.track.toml");
    assert!(l.unread.is_empty(), "{:?}", l.unread);
    let t = &l.track;
    assert_eq!(t.id, "blender-loop");
    // Its art is all its own (the checker, its own sky), so it names no host.
    assert_eq!(t.host, None);
    let path = &t.ai.paths[0];
    assert_eq!(path.points.len(), 64);
    assert_eq!((path.entry, path.exit), (Some(0), Some(0)));
    assert_eq!(t.ai.junctions.len(), 1);
    assert_eq!(
        t.nodes.iter().map(|n| n.kind).collect::<Vec<_>>(),
        [
            oag_vex::collision::SurfaceKind::Floor,
            oag_vex::collision::SurfaceKind::Wall
        ]
    );
    assert_eq!((t.speedup_pads.len(), t.weapon_pads.len()), (1, 1));
    // Progress runs 0 to just under 1 and rises at every point.
    assert_eq!(path.points[0].progress, 0.0);
    assert!(
        path.points
            .windows(2)
            .all(|w| w[0].progress < w[1].progress)
    );
    assert!(path.points.last().unwrap().progress < 1.0);
    // The frame is orthonormal and level on a flat loop.
    for p in &path.points {
        let len = |v: [f32; 3]| (v[0] * v[0] + v[1] * v[1] + v[2] * v[2]).sqrt();
        for v in [p.tangent, p.lateral, p.down] {
            assert!((len(v) - 1.0).abs() < 1e-5, "{v:?}");
        }
        assert!(p.pos[1].abs() < 1e-3 && p.down[1] < -0.999, "{p:?}");
    }
    // The start slot sits 154 units back along the ring from point 0, facing roughly where the line runs.
    let d = |a: [f32; 3], b: [f32; 3]| {
        ((a[0] - b[0]).powi(2) + (a[1] - b[1]).powi(2) + (a[2] - b[2]).powi(2)).sqrt()
    };
    let behind = d(t.start.position, path.points[0].pos);
    assert!(
        (100.0..=154.0).contains(&behind),
        "start is {behind} from the line"
    );
    let f = path.points[0].tangent;
    assert!(t.start.forward[0] * f[0] + t.start.forward[2] * f[2] > 0.9);
}

/// The art the add-on writes (`scripts/blender/oag_track/scene_art.py`, ADR-0076),
/// read by the real reader. Each assertion pins one mapping, so dropping or
/// changing it fails here: the colour attribute's linear `.color` (one corner was
/// set through `.color_srgb = 0.5`, which is linear 0.214), v flipped to v-down,
/// Blender's Z-up axes, the Math node alpha clip as `oag_alpha_ref`, the object's
/// layer and shadow role, the Sun lamps, the world colour and the cover-darkened
/// light scale.
#[test]
fn the_art_authored_in_blender_reads_back_as_authored() {
    use oag_trackfile::art::{Blend, Light, ShadowRole, TextureSource};
    let l = load("blender_loop.track.toml");
    let art = l.track.art.as_ref().expect("the loop carries art");
    assert_eq!(art.meshes.len(), 1);
    let m = &art.meshes[0];
    assert_eq!(m.name, "canopy");
    assert_eq!(m.material.blend, Blend::Cutout);
    assert_eq!(m.material.alpha_ref, Some(128));
    assert_eq!(m.material.texture, Some(0));
    assert!(!m.material.culled && !m.material.lit);
    assert_eq!((m.shadow, m.layer), (ShadowRole::Cast, 2));
    assert_eq!(
        art.textures,
        [TextureSource::Image("blender_checker.png".into())]
    );
    // One quad: four corners, two triangles, every corner a vertex of its own.
    assert_eq!((m.positions.len(), m.indices.len()), (4, 6));
    // Blender (950, -60, 40) is the format's (950, 40, 60); the face points up.
    assert!(
        m.positions.contains(&[950.0, 40.0, 60.0]),
        "{:?}",
        m.positions
    );
    assert!(m.normals.iter().all(|n| n[1] == 1.0), "{:?}", m.normals);
    // Blender v 0.25 is the disc's v-down 0.75.
    assert!(m.texcoords.contains(&[1.0, 0.75]), "{:?}", m.texcoords);
    let srgb_half = m.colours[0];
    assert!(
        (srgb_half[0] - 0.214_041).abs() < 1e-5,
        "the colour is .color (linear), not .color_srgb: {srgb_half:?}"
    );
    assert_eq!(&m.colours[1..], [[0.25, 0.5, 1.0, 1.0]; 3]);

    let sun = art.sun.expect("the Sun lamp is the sun");
    assert!((sun.direction[1] - 1.0).abs() < 1e-6, "{:?}", sun.direction);
    assert_eq!(sun.colour, [1.0, 0.9, 0.7]);
    assert_eq!(
        (sun.intensity, sun.angular_diameter, sun.shadows),
        (1.0, 2.0, true)
    );
    assert_eq!(art.ambient, Some([0.1, 0.12, 0.15]));
    let [
        Light::Directional {
            direction,
            colour,
            intensity,
        },
    ] = art.lights.as_slice()
    else {
        panic!("one fill light: {:?}", art.lights);
    };
    assert!((direction[2] + 1.0).abs() < 1e-6, "{direction:?}");
    assert_eq!((*colour, *intensity), ([0.2, 0.25, 0.4], 0.5));
    assert_eq!(art.sky, None);
    // Its own sky: the gradient, with the checker overhead (face 2, +Y).
    assert_eq!(
        art.skybox,
        Some(oag_trackfile::art::Skybox {
            faces: [None, None, Some(0), None, None, None],
            zenith: Some([0.1, 0.25, 0.6]),
            horizon: Some([0.7, 0.75, 0.8]),
        })
    );
    assert_eq!(art.lens_flare.and_then(|f| f.atlas), Some(0));

    // The canopy casts over the line: the points under it are darkened, the rest are not.
    let light: Vec<[u8; 4]> = l.track.ai.paths[0]
        .points
        .iter()
        .map(|p| p.light_scale)
        .collect();
    let covered = light.iter().filter(|b| **b == [96, 96, 255, 255]).count();
    let open = light.iter().filter(|b| **b == [255; 4]).count();
    assert!(covered >= 1 && covered + open == light.len(), "{light:?}");

    // The texture is the generated checker beside the manifest: a 64x64 RGBA PNG.
    let png = std::fs::read(
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/fixtures/blender_checker.png"),
    )
    .expect("the checker sits beside the manifest");
    assert_eq!(&png[12..16], b"IHDR");
    assert_eq!(
        (&png[16..20], &png[20..24], png[25]),
        (&[0, 0, 0, 64][..], &[0, 0, 0, 64][..], 6)
    );
}

/// The loop, imported by the add-on and exported again, is the same track: the
/// importer's art (meshes, materials, lamps, world, flare) writes back what it read.
#[test]
fn the_loop_imported_into_blender_and_exported_again_is_the_same_track() {
    let (a, b) = (
        load("blender_loop.track.toml"),
        load("blender_loop.reexport.track.toml"),
    );
    assert!(b.unread.is_empty(), "{:?}", b.unread);
    assert!(b.track.art.is_some());
    assert_eq!(a.track, b.track);
}
